27	// This is a dolt implementation of the MySQL type Point, thus most of the functionality
28	// within is directly reliant on the go-mysql-server implementation.
29	type pointType struct {
30		sqlPointType gmstypes.PointType
31		enc          val.Encoding
32	}
33	
34	var _ TypeInfo = (*pointType)(nil)
35	
36	var PointType = &pointType{sqlPointType: gmstypes.PointType{}}
37	
38	// Equals implements TypeInfo interface.
39	func (ti *pointType) Equals(other TypeInfo) bool {
40		if other == nil {
41			return false
42		}
43		if o, ok := other.(*pointType); ok {
44			// if either ti or other has defined SRID, then check SRID value; otherwise,
45			return ((!ti.sqlPointType.DefinedSRID && !o.sqlPointType.DefinedSRID) || ti.sqlPointType.SRID == o.sqlPointType.SRID) &&
46				ti.Encoding() == o.Encoding()
47		}
48		return false
49	}
50	
51	// NomsKind implements TypeInfo interface.
52	func (ti *pointType) NomsKind() types.NomsKind {
53		return types.PointKind
54	}
55	
56	// String implements TypeInfo interface.
57	func (ti *pointType) String() string {
58		return "Point"
59	}
60	
61	// Encoding implements TypeInfo interface.
62	func (ti *pointType) Encoding() val.Encoding {
63		if ti.enc != 0 {
64			return ti.enc
65		}
66		if UseAdaptiveEncoding {
67			return val.GeomAdaptiveEnc
68		}
69		return val.GeomAddrEnc
70	}
71	
72	// WithEncoding implements TypeInfo interface.
73	func (ti *pointType) WithEncoding(enc val.Encoding) TypeInfo {
74		if enc != val.GeomAddrEnc && enc != val.GeometryEnc && enc != val.GeomAdaptiveEnc {
75			panic(fmt.Errorf("encoding %v is not valid for %T", enc, ti))
76		}
77		return &pointType{sqlPointType: ti.sqlPointType, enc: enc}
78	}
79	
80	// ToSqlType implements TypeInfo interface.
81	func (ti *pointType) ToSqlType() sql.Type {
82		return ti.sqlPointType
83	}
84	
85	func CreatePointTypeFromSqlPointType(sqlPointType gmstypes.PointType) TypeInfo {
86		return &pointType{sqlPointType: sqlPointType}
87	}
