26	// As a type, this is modeled more after MySQL's story for binary data. There, it's treated
27	// as a string that is interpreted as raw bytes, rather than as a bespoke data structure,
28	// and thus this is mirrored here in its implementation. This will minimize any differences
29	// that could arise.
30	//
31	// This type handles the BLOB types. BINARY and VARBINARY are handled by inlineBlobType.
32	type varBinaryType struct {
33		sqlBinaryType sql.StringType
34		enc           val.Encoding // 0 means use default based on UseAdaptiveEncoding
35	}
36	
37	var _ TypeInfo = (*varBinaryType)(nil)
38	
39	// Equals implements TypeInfo interface.
40	func (ti *varBinaryType) Equals(other TypeInfo) bool {
41		if other == nil {
42			return false
43		}
44		if ti2, ok := other.(*varBinaryType); ok {
45			return ti.sqlBinaryType.MaxCharacterLength() == ti2.sqlBinaryType.MaxCharacterLength() &&
46				ti.Encoding() == ti2.Encoding()
47		}
48		return false
49	}
50	
51	// NomsKind implements TypeInfo interface.
52	func (ti *varBinaryType) NomsKind() types.NomsKind {
53		return types.BlobKind
54	}
55	
56	// String implements TypeInfo interface.
57	func (ti *varBinaryType) String() string {
58		return fmt.Sprintf(`VarBinary(%v)`, ti.sqlBinaryType.MaxCharacterLength())
59	}
60	
61	// Encoding implements TypeInfo interface.
62	func (ti *varBinaryType) Encoding() val.Encoding {
63		if ti.enc != 0 {
64			return ti.enc
65		}
66		if UseAdaptiveEncoding {
67			return val.BytesAdaptiveEnc
68		}
69		return val.BytesAddrEnc
70	}
71	
72	// WithEncoding implements TypeInfo interface.
73	func (ti *varBinaryType) WithEncoding(enc val.Encoding) TypeInfo {
74		switch enc {
75		case val.BytesAdaptiveEnc, val.BytesAddrEnc:
76		default:
77			panic(fmt.Errorf("encoding %v is not valid for %T", enc, ti))
78		}
79		return &varBinaryType{sqlBinaryType: ti.sqlBinaryType, enc: enc}
80	}
81	
82	// ToSqlType implements TypeInfo interface.
83	func (ti *varBinaryType) ToSqlType() sql.Type {
84		return ti.sqlBinaryType
85	}
