func TestScratchPreserve(t *testing.T) {
	old := UseAdaptiveEncoding
	UseAdaptiveEncoding = true
	defer func() { UseAdaptiveEncoding = old }()

	// nil existing -> fresh unchanged
	fresh := &blobStringType{sqlStringType: gmstypes.LongText}
	if PreserveAdaptiveEncoding(nil, fresh) != fresh {
		t.Fatal("nil existing should return fresh")
	}
	// nil fresh -> nil
	if PreserveAdaptiveEncoding(fresh, nil) != nil {
		t.Fatal("nil fresh should return nil")
	}
	// text legacy addr preserved, semantics unchanged
	existing := (&blobStringType{sqlStringType: gmstypes.Text}).WithEncoding(val.StringAddrEnc)
	got := PreserveAdaptiveEncoding(existing, fresh)
	if got.Encoding() != val.StringAddrEnc {
		t.Fatalf("want StringAddrEnc got %v", got.Encoding())
	}
	if got.(*blobStringType).sqlStringType.MaxCharacterLength() != gmstypes.LongText.MaxCharacterLength() {
		t.Fatal("semantics changed")
	}
	// blob
	eb := (&varBinaryType{sqlBinaryType: gmstypes.Blob}).WithEncoding(val.BytesAddrEnc)
	fb := &varBinaryType{sqlBinaryType: gmstypes.LongBlob}
	if PreserveAdaptiveEncoding(eb, fb).Encoding() != val.BytesAddrEnc {
		t.Fatal("blob addr not preserved")
	}
	// json
	ej := (&jsonType{}).WithEncoding(val.JSONAddrEnc)
	if PreserveAdaptiveEncoding(ej, &jsonType{}).Encoding() != val.JSONAddrEnc {
		t.Fatal("json addr not preserved")
	}
	// geometry same concrete type
	ep := (&pointType{}).WithEncoding(val.GeomAddrEnc)
	if PreserveAdaptiveEncoding(ep, &pointType{}).Encoding() != val.GeomAddrEnc {
		t.Fatal("point addr not preserved")
	}
	// geometry different concrete -> no-op
	if PreserveAdaptiveEncoding(ep, &linestringType{}).Encoding() != val.GeomAdaptiveEnc {
		t.Fatal("point->line should not preserve")
	}
	// cross family varString->blobString no-op
	vs := &varStringType{sqlStringType: gmstypes.MustCreateStringWithDefaults(1, 100)}
	if PreserveAdaptiveEncoding(vs, fresh).Encoding() != val.StringAdaptiveEnc {
		t.Fatal("varchar->text should not preserve")
	}
	// integer no-op
	i8 := &intType{sqlIntType: gmstypes.Int8}
	if PreserveAdaptiveEncoding(i8, i8) != i8 {
		// applying same enc on integers should return fresh unchanged (identity)
		t.Fatalf("int should be no-op returning fresh")
	}
}
